const resultado = JSON.parse($input.first().json.text);

const memoria = $('Preparar Memoria - Cliente Recurrente').isExecuted
  ? $('Preparar Memoria - Cliente Recurrente').first().json
  : $('Preparar Memoria - Cliente Nuevo').first().json;

const datosEntrada = $('Preparar Datos de Entrada').first().json;

return [{
  json: {
    tipo_consulta: resultado.tipo_consulta,
    producto: resultado.producto,
    consulta: memoria.chatInput,
    sessionId: memoria.sessionId,
    nombre_cliente: datosEntrada.nombre_cliente,
    email_cliente: datosEntrada.email_cliente,
    asunto: datosEntrada.asunto,
    resumen_consolidado: memoria.resumen_consolidado,
    estado_del_caso: memoria.estado_del_caso,
    datos_clave: memoria.datos_clave,
    recordId: memoria.recordId,
    cantidad_mensajes: memoria.cantidad_mensajes
  }
}];

const entrada = $('If').first().json;
const resumen = JSON.parse($json.text);

return {
  json: {
    ...entrada,
    ...resumen
  }
};

